/**
 * Inicializa el objeto TFT_ST7735.
 * @param CS_pin Número del pin asociado al Chip Select.
 * @param DC_pin Número del pin asociado al selector Dato/Comando.
 * @param MOSI_pin Número del pin asociado al MOSI.
 * @param SCLK_pin Número del pin asociado al Clock.
 * @param RST_pin Número del pin asociado al Reset.
 */
TFT_ST7735::TFT_ST7735(int CS_pin, int DC_pin, int MOSI_pin, int SCLK_pin, int RST_pin){
    _CS_pin = CS_pin;
    _DC_pin = DC_pin;
    _MOSI_pin = MOSI_pin;
    _SCLK_pin = SCLK_pin;
    _RST_pin = RST_pin;
    
}

/**
 * Inicializa la pantalla y la pinta completamente negra.
 */
void TFT_ST7735::begin(){
    _tft = Adafruit_ST7735(_CS_pin, _DC_pin, _MOSI_pin, _SCLK_pin, _RST_pin);
    _tft.initR(INITR_BLACKTAB);  // Initialize the display
    _tft.fillScreen(ST77XX_BLACK); // Clear the screen
    condor_logo(14,0);
    delay(500);
}

/**
 * Escribe texto en la pantalla.
 * @param color Color del texto.
 * @param text Un string con el texto a imprimir.
 * @param size Tamaño de fuente.
 * @param posX La posición X del inicio del texto.
 * @param posY La posición Y del inicio del texto.
 */
void TFT_ST7735::write(int16_t color, String text, int size, int pos_X, int pos_Y){
    _tft.setTextColor(color); // Set text color
    _tft.setTextSize(size); // Set text size
    _tft.setCursor(pos_X, pos_Y); // Set text position
    _tft.println(text);
}

/**
 * Dibuja el logo de Cóndor de 100x100 en la posición indicada.
 * @param posX La posición X del inicio del logo.
 * @param posY La posición Y del inicio del logo.
 */
void TFT_ST7735::condor_logo(int posX, int posY){
    _tft.drawBitmap(posX, posY, logo, 100, 100, ST7735_WHITE);
}


void TFT_ST7735::update_orientation(int16_t x_len, int16_t y_len, short roll, short pitch){
    _tft.fillScreen(ST77XX_BLACK); // Clear the screen
    

    int16_t y_middle = static_cast<int16_t>(y_len/2);
    int16_t x0 = static_cast<int16_t>(x_len/2); //Centro de la pantalla
    int16_t y0 = y_middle + static_cast<int16_t>((pitch/180)*y_middle); //Centro de la pantalla desfasado por desplazamiento del pitch.
    double pendiente = tan(roll*PI/180);
    
    _tft.startWrite();
    for (int x = 0; x < 128; x++){
        for (int y = 0; y < 160; y++){
            if (y > (x-x0)*pendiente - y0){
                _tft.writePixel(x, y, 39458); //El 39458 es un color cercano al café en RGB565.
            }
            else{
                _tft.writePixel(x, y, 40191); //El 40191 es un color cercano al azul en RGB565.
            }
        }
    }

    

    _tft.endWrite();

    _tft.drawLine(x0 - 20, y_middle, x0 + 20, y_middle, 63488);

    /*

    for (int i = roll; i < roll + 181; i++){
        for (int j = r; j > 0; j--){
            _tft.writePixel(x0 + j*static_cast<int16_t>(cos(i*2*PI/180)), y0 + j*static_cast<int16_t>(sin(i*2*PI/180)), 40191); //El 40191 es un color cercano al azul en RGB565.
        }
    }
    */
}


void TFT_ST7735::alert(){
    write(65535,"!",5,49,20);
    write(65535, "Temperatura elevada", 1, 7, 148);
}


void TFT_ST7735::update_telemetry(API_data data, gps_data gps){
    _tft.fillScreen(ST77XX_BLACK); // Clear the screen
    write(65535, "Tonina 3", 2, 16, 5);
    write(65535, "Temp BP: " + static_cast<String>(data.temperatura_BP), 1, 5, 24);
    write(65535, "Temp BS: " + static_cast<String>(data.temperatura_BS), 1, 5, 34);
    write(65535, "Lat: " + static_cast<String>(gps.lat), 1, 5, 44);
    write(65535, "Lon: " + static_cast<String>(gps.log), 1, 5, 54);
    write(65535, "Speed: " + static_cast<String>(gps.speed), 1, 5, 64);
    write(65535, "Time: " + static_cast<String>(gps.UTC_time), 1, 5, 74);
}